      function SafeGetValue(obj, path, defaultValue = 'N/A') {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
          if (
            current === undefined ||
            current === null ||
            typeof current !== 'object' ||
            !current.hasOwnProperty(keys[i])
          ) {
            return defaultValue;
          }
          current = current[keys[i]];
        }
        if (current === undefined || current === null) {
          return defaultValue;
        }
        if (Array.isArray(current)) {
          if (current.length > 0) {
            const actualValue = current[0];
            if (typeof actualValue === 'boolean') {
              return actualValue;
            }
            return String(actualValue);
          } else {
            return defaultValue;
          }
        }
        if (typeof current === 'boolean') {
          return current;
        }
        return String(current);
      }

      // MODIFIED FUNCTION
      function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);
        if (!valueMainDisplay) return;

        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));

        // Get the part AFTER '->' if it exists, otherwise use the whole string.
        const parts = fullDisplayString.split('->');
        let workingString = (parts.length > 1 ? parts[1] : parts[0]).trim();

        // Also, remove the reason in parentheses from the end for parsing.
        let forParsingString = workingString.split('(')[0].trim();

        let numericValue = min;
        let descriptionText = '';
        let displayableText = workingString;

        const descriptionMatch = workingString.match(/\((.+)\)$/);
        if (descriptionMatch && descriptionMatch[1]) {
          descriptionText = descriptionMatch[1];
          displayableText = workingString.substring(0, descriptionMatch.index).trim();
          forParsingString = displayableText; // Update parsing string if description was found
        }

        const valueMatch = forParsingString.match(/(-?\d+(\.\d+)?)/);
        if (valueMatch) {
          numericValue = parseFloat(valueMatch[0]);
        } else if (!isNaN(parseFloat(forParsingString))) {
          numericValue = parseFloat(forParsingString);
        }

        valueMainDisplay.innerText = displayableText;
        if (valueDescDisplay) {
          valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : '';
        }

        if (progressBar) {
          numericValue = Math.max(min, Math.min(max, numericValue));
          const range = max - min;
          const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
          progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
          progressBar.style.backgroundColor = color ? color : 'var(--accent-highlight)';
        }
      }

      // MODIFIED FUNCTION
      function updateTextField(elementId, value) {
        const el = document.getElementById(elementId);
        if (el) {
          let displayValue = String(value);
          // Split the string by '->'. If it exists, take the second part (the new value).
          const parts = displayValue.split('->');
          let finalValue = parts.length > 1 ? parts[1] : parts[0];

          // Now, remove the reason part (e.g., " (some reason)") from the finalValue
          finalValue = finalValue.split('(')[0].trim();

          el.innerText = finalValue;
        }
      }

      async function initDisplay() {
        try {
          const messages = await getChatMessages(getCurrentMessageId());
          if (!messages || messages.length === 0 || !messages[0].data) {
            document.getElementById('status-card').innerHTML =
              "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
            return;
          }
          const gameData = messages[0].data;
          const characterData = gameData.display_data || gameData.stat_data;
          if (!characterData) {
            document.getElementById('status-card').innerHTML =
              "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
            return;
          }

          updateTextField('world-time', SafeGetValue(characterData, '世界.当前时间'));
          updateTextField('world-location', SafeGetValue(characterData, '世界.当前地点'));
          updateTextField('world-characters', SafeGetValue(characterData, '世界.当前场景人物'));
          updateTextField('family-assets', SafeGetValue(characterData, '{{user}}.家族资产'));

          const characters = ['suqingyan', 'tangyuan', 'qinshuang', 'liuruyan', 'shenjingshu'];
          const characterNames = {
            suqingyan: '苏清颜',
            tangyuan: '唐鸢',
            qinshuang: '秦霜',
            liuruyan: '柳如烟',
            shenjingshu: '沈静姝',
          };

          characters.forEach(char => {
            const name = characterNames[char];
            updateProgressBar(
              `${char}-affection-bar`,
              `${char}-affection`,
              `${char}-affection-desc`,
              SafeGetValue(characterData, `${name}.对{{user}}的好感度`),
              0,
              100,
            );
            updateTextField(`${char}-relation`, SafeGetValue(characterData, `${name}.与{{user}}的关系`));
            updateTextField(`${char}-impression`, SafeGetValue(characterData, `${name}.对{{user}}的看法`));
            updateTextField(`${char}-experience`, SafeGetValue(characterData, `${name}.与{{user}}的重要经历`));
          });

          switchTab('world');
        } catch (error) {
          document.getElementById(
            'status-card',
          ).innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
      }

      function switchTab(tabId) {
        const contents = document.querySelectorAll('.tab-content');
        contents.forEach(content => {
          content.style.display = 'none';
        });

        const buttons = document.querySelectorAll('.tab-button');
        buttons.forEach(button => {
          button.classList.remove('active');
        });

        const selectedContent = document.getElementById('tab-' + tabId);
        if (selectedContent) {
          selectedContent.style.display = 'block';
        }

        const selectedButton = document.getElementById('btn-' + tabId);
        if (selectedButton) {
          selectedButton.classList.add('active');
        }
      }

      document.addEventListener('DOMContentLoaded', initDisplay);
